PHASE_INC = {chess.PAWN:0, chess.KNIGHT:1, chess.BISHOP:1, chess.ROOK:2, chess.QUEEN:4, chess.KING:0}

# Precompute: for each (piece_type, color, square) -> (mg, eg) score from white's perspective
MG = {}
EG = {}
for pt in chess.PIECE_TYPES:
    for sq in chess.SQUARES:
        # tables are indexed with a8=0 ... h1=63 (rank 8 first). python-chess: a1=0.
        wsq = chess.square_mirror(sq)  # flip so that index 0 == a8
        MG[(pt, chess.WHITE, sq)] = MG_VAL[pt] + MG_T[pt][wsq]
        EG[(pt, chess.WHITE, sq)] = EG_VAL[pt] + EG_T[pt][wsq]
        MG[(pt, chess.BLACK, sq)] = -(MG_VAL[pt] + MG_T[pt][sq])
        EG[(pt, chess.BLACK, sq)] = -(EG_VAL[pt] + EG_T[pt][sq])

MATE = 100000

def evaluate(board):
    """Return score from side-to-move perspective."""
    mg = 0; eg = 0; phase = 0
    pm = board.piece_map()
    for sq, p in pm.items():
        k = (p.piece_type, p.color, sq)
        mg += MG[k]; eg += EG[k]; phase += PHASE_INC[p.piece_type]
    if phase > 24: phase = 24
    score = (mg * phase + eg * (24 - phase)) // 24
    # small bonuses: bishop pair, mobility-ish via pawn structure ignored for speed
    return score if board.turn == chess.WHITE else -score

PV_VAL = {chess.PAWN:1, chess.KNIGHT:3, chess.BISHOP:3, chess.ROOK:5, chess.QUEEN:9, chess.KING:20}

class Searcher:
    def __init__(self):
        self.tt = {}
        self.nodes = 0
        self.killers = defaultdict(lambda: [None, None])
        self.history = defaultdict(int)
        self.stop_time = None
        self.stopped = False

    def check_time(self):
        if self.stop_time and (self.nodes & 1023) == 0 and time.time() > self.stop_time:
            self.stopped = True

    def order_moves(self, board, moves, tt_move, ply):
        scored = []
        kl = self.killers[ply]
        for m in moves:
            if m == tt_move:
                s = 10_000_000
            elif board.is_capture(m):
                victim = board.piece_type_at(m.to_square)
                if victim is None: victim = chess.PAWN  # en passant
                attacker = board.piece_type_at(m.from_square)
                s = 1_000_000 + PV_VAL[victim]*100 - PV_VAL[attacker]
            elif m.promotion:
                s = 900_000
            elif m in kl:
                s = 800_000
            else:
                s = self.history[(board.turn, m.from_square, m.to_square)]
            scored.append((s, m))
        scored.sort(key=lambda x: -x[0])
        return [m for _, m in scored]

    def qsearch(self, board, alpha, beta, ply):
        self.nodes += 1
        self.check_time()
        stand = evaluate(board)
        if stand >= beta:
            return stand
        if stand > alpha:
            alpha = stand
        moves = [m for m in board.legal_moves if board.is_capture(m) or m.promotion]
        # order MVV-LVA
        def key(m):
            v = board.piece_type_at(m.to_square) or chess.PAWN
            return -(PV_VAL[v]*100 - PV_VAL[board.piece_type_at(m.from_square)])
        moves.sort(key=key)
        for m in moves:
            # delta pruning
            v = board.piece_type_at(m.to_square)
            gain = (MG_VAL[v] if v else 82) + (900 if m.promotion else 0)
            if stand + gain + 200 < alpha:
                continue
            board.push(m)
            score = -self.qsearch(board, -beta, -alpha, ply+1)
            board.pop()
            if self.stopped: return alpha
            if score >= beta:
                return score
            if score > alpha:
                alpha = score
        return alpha

    def search(self, board, depth, alpha, beta, ply, null_ok=True):
        self.nodes += 1
        self.check_time()
        if self.stopped: return 0
        if ply > 0 and (board.is_repetition(2) or board.halfmove_clock >= 100):
            return 0
        in_check = board.is_check()
        if in_check: depth += 1  # check extension
        if depth <= 0:
            return self.qsearch(board, alpha, beta, ply)
        alpha_orig = alpha
        key = board._transposition_key()
        tt_move = None
        ent = self.tt.get(key)
        if ent is not None:
            tdepth, tscore, tflag, tmove = ent
            tt_move = tmove
            if tdepth >= depth and ply > 0:
                if tflag == 0: return tscore
                if tflag == 1 and tscore >= beta: return tscore
                if tflag == 2 and tscore <= alpha: return tscore
        # null move pruning
        if null_ok and not in_check and depth >= 3 and ply > 0:
            # ensure non-pawn material
            if board.occupied_co[board.turn] & ~(board.pawns | board.kings):
                board.push(chess.Move.null())
                score = -self.search(board, depth - 3, -beta, -beta + 1, ply+1, False)
                board.pop()
                if self.stopped: return 0
                if score >= beta:
                    return beta
        moves = list(board.legal_moves)
        if not moves:
            if in_check: return -MATE + ply
            return 0
        moves = self.order_moves(board, moves, tt_move, ply)
        best = -MATE*2; best_move = None
        for i, m in enumerate(moves):
            board.push(m)
            gives_check = board.is_check()
            # late move reductions
            if i >= 4 and depth >= 3 and not in_check and not gives_check and not board.is_capture(m) if False else False:
                pass
            reduce = 0
            if i >= 4 and depth >= 3 and not in_check and not gives_check and not m.promotion and not self._was_capture(board):
                reduce = 1 if i < 12 else 2
            if i == 0:
                score = -self.search(board, depth-1, -beta, -alpha, ply+1)
            else:
                score = -self.search(board, depth-1-reduce, -alpha-1, -alpha, ply+1)
                if score > alpha and (reduce > 0 or score < beta):
                    score = -self.search(board, depth-1, -beta, -alpha, ply+1)
            board.pop()
            if self.stopped: return 0
            if score > best:
                best = score; best_move = m
            if score > alpha:
                alpha = score
            if alpha >= beta:
                if not board.is_capture(m):
                    kl = self.killers[ply]
                    if kl[0] != m:
                        kl[1] = kl[0]; kl[0] = m
                    self.history[(board.turn, m.from_square, m.to_square)] += depth*depth
                break
        flag = 0
        if best <= alpha_orig: flag = 2
        elif best >= beta: flag = 1
        self.tt[key] = (depth, best, flag, best_move)
        return best

    def _was_capture(self, board):
        # after push: check if last move was capture
        m = board.peek()
        return board.is_capture(m) if False else (m in self._cap_cache if False else self._last_capture(board, m))

    def _last_capture(self, board, m):
        # after the move has been pushed, we can't easily ask; use move stack analysis
        board.pop()
        c = board.is_capture(m)
        board.push(m)
        return c

    def iterative(self, board, max_time, max_depth=64, verbose=True):
        self.stop_time = time.time() + max_time
        self.stopped = False
        self.nodes = 0
        best_move = None
        best_score = 0
        start = time.time()
        moves = list(board.legal_moves)
        if len(moves) == 1:
            return moves[0], 0
        for depth in range(1, max_depth+1):
            alpha, beta = -MATE*2, MATE*2
            if depth >= 4:
                alpha, beta = best_score - 60, best_score + 60
            while True:
                score = self.search(board, depth, alpha, beta, 0)
                if self.stopped: break
                if score <= alpha:
                    alpha -= 200
                    if alpha < -MATE: alpha = -MATE*2
                elif score >= beta:
                    beta += 200
                    if beta > MATE: beta = MATE*2
                else:
                    break
            if self.stopped:
                break
            ent = self.tt.get(board._transposition_key())
            if ent and ent[3] is not None:
                best_move = ent[3]; best_score = score
            if verbose:
                pv = self.get_pv(board)
                print(f"depth {depth} score {score} nodes {self.nodes} time {time.time()-start:.1f} pv {' '.join(pv)}", flush=True)
            if abs(score) > MATE - 1000:
                break
            if time.time() - start > max_time * 0.4:
                break
        return best_move, best_score

    def get_pv(self, board, maxlen=12):
        pv = []
        b = board.copy()
        for _ in range(maxlen):
            ent = self.tt.get(b._transposition_key())
            if not ent or ent[3] is None: break
            m = ent[3]
            if m not in b.legal_moves: break
            pv.append(m.uci()); b.push(m)
        return pv

